package com.example.textapi.controller;

import static org.mockito.Mockito.mock;
import com.example.textapi.service.TextService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.*;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.reset;
import static org.mockito.Mockito.when;
import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(MockitoExtension.class)
public class TextControllerGeneratedAiTests {

    @Mock
    private TextService textService;

    @InjectMocks
    private TextController textController;

    @BeforeEach
    void setUp() {
        reset(textService);
    }

    @Test
    void testHelloWorldReturnsExpectedString() {
        // GIVEN: TextService returns a fixed hello world string
        String expected = "Hello, World!";
        when(textService.helloworld()).thenReturn(expected);

        // WHEN: helloWorld endpoint is called
        String result = textController.helloWorld();

        // THEN: The returned string should match expected
        assertEquals(expected, result);
    }

    @Test
    void testReverseReturnsReversedString() {
        // GIVEN: Input string and expected reversed output
        String input = "abcdef";
        String expected = "fedcba";
        when(textService.reverse(input)).thenReturn(expected);

        // WHEN: reverse endpoint is called
        String result = textController.reverse(input);

        // THEN: The returned string should be reversed
        assertEquals(expected, result);
    }

    @Test
    void testUppercaseReturnsUppercaseString() {
        // GIVEN: Input string and expected uppercase output
        String input = "Hello World";
        String expected = "HELLO WORLD";
        when(textService.uppercase(input)).thenReturn(expected);

        // WHEN: uppercase endpoint is called
        String result = textController.uppercase(input);

        // THEN: The returned string should be uppercase
        assertEquals(expected, result);
    }

    @Test
    void testStatsReturnsStatsMap() {
        // GIVEN: Input string and expected stats map
        String input = "Hello World\nHello";
        Map<String, Object> expected = new HashMap<>();
        expected.put("length", 17);
        expected.put("wordCount", 3);
        expected.put("lineCount", 2);
        expected.put("VowelCount", 5);
        expected.put("ConsonantCount", 7);
        expected.put("RepeatedWords", Arrays.asList("hello : 2"));

        when(textService.stats(input)).thenReturn(expected);

        // WHEN: stats endpoint is called
        Map<String, Object> result = textController.stats(input);

        // THEN: The returned map should match expected
        assertEquals(expected, result);
    }

    @Test
    void testReplaceReturnsReplacedString() {
        // GIVEN: Input string, target, replacement, and expected output
        String input = "foo bar foo";
        String target = "foo";
        String replacement = "baz";
        String expected = "baz bar baz";
        when(textService.replace(input, target, replacement)).thenReturn(expected);

        // WHEN: replace endpoint is called
        String result = textController.replace(target, replacement, input);

        // THEN: The returned string should have replacements
        assertEquals(expected, result);
    }

    @Test
    void testRemoveVowelsReturnsStringWithoutVowels() {
        // GIVEN: Input string and expected output
        String input = "Hello World";
        String expected = "Hll Wrld";
        when(textService.removeVowels(input)).thenReturn(expected);

        // WHEN: removeVowels endpoint is called
        String result = textController.removeVowels(input);

        // THEN: The returned string should have vowels removed
        assertEquals(expected, result);
    }

    @Test
    void testRemoveConsonantsReturnsStringWithoutConsonants() {
        // GIVEN: Input string and expected output
        String input = "Hello World";
        String expected = "eo o";
        when(textService.removeConsonants(input)).thenReturn(expected);

        // WHEN: removeConsonants endpoint is called
        String result = textController.removeConsonants(input);

        // THEN: The returned string should have consonants removed
        assertEquals(expected, result);
    }

    @Test
    void testCountOccurrenceReturnsCorrectCount() {
        // GIVEN: Input string, keyword, and expected count
        String input = "apple banana apple orange apple";
        String keyword = "apple";
        int expected = 3;
        when(textService.countOccurrence(input, keyword)).thenReturn(expected);

        // WHEN: countOccurrence endpoint is called
        int result = textController.countOccurrence(keyword, input);

        // THEN: The returned count should match expected
        assertEquals(expected, result);
    }

    @Test
    void testJsonToYamlReturnsConvertedYaml() {
        // GIVEN: Input JSON and expected YAML output
        String json = "{\"name\":\"John\",\"age\":30}";
        String expectedYaml = "---\nname: \"John\"\nage: 30\n";
        when(textService.convertJsonToYaml(json)).thenReturn(expectedYaml);

        // WHEN: jsonToYaml endpoint is called
        String result = textController.jsonToYaml(json);

        // THEN: The returned YAML should match expected
        assertEquals(expectedYaml, result);
    }

    @Test
    void testJsonToXmlReturnsConvertedXml() {
        // GIVEN: Input JSON and expected XML output
        String json = "{\"name\":\"John\",\"age\":30}";
        String expectedXml = "<ObjectNode><name>John</name><age>30</age></ObjectNode>";
        when(textService.convertJsonToXml(json)).thenReturn(expectedXml);

        // WHEN: jsonToXml endpoint is called
        String result = textController.jsonToXml(json);

        // THEN: The returned XML should match expected
        assertEquals(expectedXml, result);
    }
}

